/* wkmidi.c — implementation of wkmidi.h over the wit-bindgen C bindings.
 *
 * The bindings (gen/wkmidi.h + gen/wkmidi.c + gen/wkmidi_component_type.o)
 * are regenerated by each consumer's build.sh:
 *
 *     wit-bindgen c --world wkmidi ../midi-compat/wit --out-dir ../midi-compat/gen
 *
 * State is a single global input resource: wk gives a node one MIDI inbox,
 * and the C apps this shim exists for (a soundfont synth, ...) assume one
 * input stream. The resource is intentionally never dropped — it lives in a
 * static for the guest's lifetime, like wkaudio's context + queue.
 */
#include "wkmidi.h"

#include <string.h>

#include "gen/wkmidi.h"

static struct {
    int open;
    wk_midi_midi_own_input_t input;
} G;

int wkmidi_open(void)
{
    if (G.open)
        return -1;
    G.input = wk_midi_midi_constructor_input();
    G.open = 1;
    return 0;
}

int wkmidi_recv(uint8_t *buf, size_t cap)
{
    if (!G.open)
        return 0;
    wkmidi_list_u8_t msg;
    if (!wk_midi_midi_method_input_receive(wk_midi_midi_borrow_input(G.input), &msg))
        return 0; /* queue empty */
    size_t n = msg.len < cap ? msg.len : cap;
    memcpy(buf, msg.ptr, n);
    /* The option's list is canonical-ABI-allocated in guest memory; free it
     * now that the bytes are copied out. */
    wkmidi_list_u8_free(&msg);
    return (int)n;
}
